-- قاعدة بيانات مؤطري مراكز ومكاتب التصويت - بلدية الخيثر (ولاية البيض)
-- انتخاب أعضاء المجالس الشعبية البلدية والولائية 28 نوفمبر 2026
-- إجمالي المراكز: 5 | إجمالي المؤطرين: 285

SET NAMES utf8mb4;

BEGIN TRANSACTION;
CREATE TABLE centers (
    center_id INTEGER PRIMARY KEY AUTOINCREMENT,
    wilaya TEXT NOT NULL DEFAULT 'البيض',
    commune TEXT NOT NULL DEFAULT 'الخيثر',
    center_name TEXT NOT NULL UNIQUE
);
CREATE TABLE election_staff (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    center_id INTEGER NOT NULL,
    center_name TEXT NOT NULL,
    page_number INTEGER NOT NULL,
    list_type TEXT NOT NULL,
    office_name TEXT NOT NULL,
    last_name_ar TEXT NOT NULL,
    first_name_ar TEXT NOT NULL,
    nom_fr TEXT NOT NULL,
    prenom_fr TEXT NOT NULL,
    birth_date TEXT NOT NULL,
    birth_place TEXT NOT NULL,
    election_commune TEXT NOT NULL,
    role_title TEXT NOT NULL,
    FOREIGN KEY (center_id) REFERENCES centers(center_id)
);
CREATE INDEX idx_staff_center ON election_staff(center_id);
CREATE INDEX idx_staff_office ON election_staff(office_name);
CREATE INDEX idx_staff_name_ar ON election_staff(last_name_ar, first_name_ar);
CREATE INDEX idx_staff_nom_fr ON election_staff(nom_fr, prenom_fr);
CREATE VIEW v_summary_by_center AS
SELECT 
    c.center_id,
    c.center_name AS المركز,
    COUNT(s.id) AS إجمالي_المؤطرين,
    SUM(CASE WHEN s.list_type = 'مؤطري مركز التصويت' THEN 1 ELSE 0 END) AS مؤطري_المركز,
    SUM(CASE WHEN s.list_type = 'المجالس الشعبية البلدية' THEN 1 ELSE 0 END) AS مؤطري_البلدية,
    SUM(CASE WHEN s.list_type = 'المجالس الشعبية الولائية' THEN 1 ELSE 0 END) AS مؤطري_الولاية
FROM centers c
LEFT JOIN election_staff s ON c.center_id = s.center_id
GROUP BY c.center_id, c.center_name;
DELETE FROM "sqlite_sequence";
COMMIT;
